}

func matchesString(c constraint, v string) bool {
	value := c.Value
	switch c.Operator {
	case opEQ:
		return value == v
	case opNEQ:
		return value != v
	case opEmpty:
		return len(strings.TrimSpace(v)) == 0
	case opNotEmpty:
		return len(strings.TrimSpace(v)) != 0
	case opPrefix:
		return strings.HasPrefix(strings.TrimSpace(v), value)
	case opSuffix:
		return strings.HasSuffix(strings.TrimSpace(v), value)
	}
	return false
}

func matchesNumber(c constraint, v string) (bool, error) {
	switch c.Operator {
	case opNotPresent:
		return len(strings.TrimSpace(v)) == 0, nil
	case opPresent:
		return len(strings.TrimSpace(v)) != 0, nil
	}

	// can't parse an empty string
	if v == "" {
		return false, nil
	}

	n, err := strconv.ParseFloat(v, 64)
	if err != nil {
		return false, fmt.Errorf("parsing number from %q", v)
	}

	value, err := strconv.ParseFloat(c.Value, 64)
	if err != nil {
		return false, fmt.Errorf("parsing number from %q", c.Value)
	}

	switch c.Operator {
	case opEQ:
		return value == n, nil
	case opNEQ:
		return value != n, nil
	case opLT:
		return n < value, nil
	case opLTE:
		return n <= value, nil
	case opGT:
		return n > value, nil
	case opGTE:
		return n >= value, nil
	}

	return false, nil
}

func matchesBool(c constraint, v string) (bool, error) {
	switch c.Operator {
	case opNotPresent:
		return len(strings.TrimSpace(v)) == 0, nil
	case opPresent:
		return len(strings.TrimSpace(v)) != 0, nil
	}

	// can't parse an empty string
	if v == "" {
		return false, nil
	}

	value, err := strconv.ParseBool(v)
	if err != nil {
		return false, fmt.Errorf("parsing boolean from %q", v)
	}

	switch c.Operator {
	case opTrue:
		return value, nil
	case opFalse:
		return !value, nil
	}

	return false, nil
}
